scripts/host_runcmd_cmd.py cat << 'EOF' > analyze_battery.py
import csv
max_temp = -float('inf')
max_row = {}
with open('data/battery_2026-10.csv', mode='r') as csvfile:
    reader = csv.DictReader(csvfile)
    for row in reader:
        try:
            temp = float(row['temperature'])
            if temp > max_temp:
                max_temp = temp
                max_row = row
        except (ValueError, KeyError):
            continue
if max_row:
    print(f'溫度最高: {max_temp}, 機器人: {max_row["robot_id"]}, 時間: {max_row["timestamp"]}')
else:
    print('找不到有效數據')
EOF
python3 analyze_battery.py && rm analyze_battery.py

